/* Nebula Access Pro v1.2.0 — commercial UI DEMO, not a security backend.
   Uses hash routing so the static build works on any basic hosting service.
   Demo users are fictional. No passwords are persisted or sent to servers. */
(() => {
  'use strict';
  const $ = (sel,ctx=document) => ctx.querySelector(sel);
  const $$ = (sel,ctx=document) => [...ctx.querySelectorAll(sel)];
  const app = $('#app');
  const navItems=[['dashboard','داشبورد','dashboard'],['users','مدیریت کاربران','users'],['secretaries','افزودن و مدیریت منشی','users'],['appointments','نوبت‌ها','calendar'],['patients','مراجعان','user'],['doctors','برنامه پزشکان','clock'],['analytics','آمار و گزارش‌ها','chart'],['activity','فعالیت‌های سیستم','activity'],['settings','تنظیمات','settings'],['profile','حساب مدیر','user']];
  const paths={logo:'<path d="M12 2 21 7v10l-9 5-9-5V7Z"/><path d="M12 7v10M7 9l5-2 5 2-5 2-5-2"/>',shield:'<path d="m12 22 7-4V6l-7-4-7 4v12z"/><path d="m9 12 2 2 4-5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 6 10 7 10-7"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M11 18h2"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',hide:'<path d="m3 3 18 18M10.6 5.1A10 10 0 0 1 12 5c6 0 10 7 10 7a16 16 0 0 1-4 4.3M6.5 6.5A17 17 0 0 0 2 12s4 7 10 7c1.3 0 2.5-.3 3.7-.9"/>',arrow:'<path d="M19 12H5m7-7-7 7 7 7"/>',spark:'<path d="m12 3 2.2 6.8L21 12l-6.8 2.2L12 21l-2.2-6.8L3 12l6.8-2.2z"/>',dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chart:'<path d="M4 19V5M4 19h16M8 15l4-5 4 2 4-7"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 1.4 1.2-2.5 3.7-1.8-.8a9 9 0 0 1-2.5 1l-.4 2h-4l-.4-2a9 9 0 0 1-2.5-1l-1.8.8-2.5-3.7L4 15a9 9 0 0 1 0-6L2.6 7.8l2.5-3.7 1.8.8a9 9 0 0 1 2.5-1l.4-2h4l.4 2a9 9 0 0 1 2.5 1l1.8-.8 2.5 3.7L19.4 9a9 9 0 0 1 0 6z"/>',logout:'<path d="M10 17l5-5-5-5M15 12H3M12 3h6a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3h-6"/>',search:'<circle cx="10.8" cy="10.8" r="7"/><path d="m16 16 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',edit:'<path d="m3 17-1 5 5-1L20 8l-5-5Z"/><path d="m13 5 5 5"/>',trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 5 5L20 7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',chevron:'<path d="m9 18 6-6-6-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-6 6-6 12 0 18M12 3c6 6 6 12 0 18"/>',bolt:'<path d="M13 2 4 14h7l-1 8 10-13h-7Z"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',refresh:'<path d="M3 11a9 9 0 0 1 15-6l3 3M21 13a9 9 0 0 1-15 6l-3-3M21 3v5h-5M3 21v-5h5"/>',moon:'<path d="M20 15A8 8 0 0 1 9 4 8 8 0 1 0 20 15Z"/>',key:'<circle cx="8" cy="15" r="5"/><path d="m12 11 9-9M18 5l3 3M15 8l3 3"/>',external:'<path d="M14 3h7v7M10 14 21 3M21 13v8H3V3h8"/>',sort:'<path d="m7 7 4-4 4 4M11 3v18m6-4-4 4-4-4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.8 9a2.5 2.5 0 1 1 4.4 1.6c-.9 1-2.2 1.1-2.2 3.4M12 18h.01"/>'};
  function icon(name,cl=''){return `<svg class="icon ${cl}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.spark}</svg>`;}
  function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function pageLink(label,href,cls='link'){return `<a href="#/${href}" class="${cls}">${label}</a>`;}
  function brand(){return `<a href="#/login" class="brand" aria-label="Nebula Access Pro - صفحه ورود"><span class="brand-glyph">${icon('logo','lg')}</span><span><strong>NEBULA <span class="text-gradient">ACCESS</span></strong><small>COMMAND INTERFACE / 1.2</small></span></a>`;}
  function demoBanner(){return `<div class="demo-banner">${icon('info','small')} <strong>نسخه نمایشی قالب:</strong> ورود، نوبت‌ها، مراجعان و مدیریت کاربران صرفاً دمو هستند؛ هیچ احراز هویت، پیامک یا ذخیره‌سازی سروری وجود ندارد.</div>`;}
  const originalUsers=[
    {id:101,name:'سارا رادمنش',phone:'09120000001',email:'sara@example.test',role:'مدیر',status:'فعال',date:'۱۴۰۵/۰۷/۱۸'},
    {id:102,name:'آرمان رستگار',phone:'09120000002',email:'arman@example.test',role:'کاربر',status:'فعال',date:'۱۴۰۵/۰۷/۱۹'},
    {id:103,name:'نرگس بهرامی',phone:'09120000003',email:'narges@example.test',role:'کاربر',status:'فعال',date:'۱۴۰۵/۰۷/۱۹'},
    {id:104,name:'پرهام وثوق',phone:'09120000004',email:'parham@example.test',role:'کاربر',status:'غیرفعال',date:'۱۴۰۵/۰۷/۲۰'},
    {id:105,name:'مهسا صادقی',phone:'09120000005',email:'mahsa@example.test',role:'کاربر',status:'فعال',date:'۱۴۰۵/۰۷/۲۱'},
    {id:106,name:'نیما فراهانی',phone:'09120000006',email:'nima@example.test',role:'کاربر',status:'در انتظار',date:'۱۴۰۵/۰۷/۲۲'},
    {id:107,name:'آوا کیانی',phone:'09120000007',email:'ava@example.test',role:'کاربر',status:'فعال',date:'۱۴۰۵/۰۷/۲۲'},
    {id:108,name:'امیر پارسایی',phone:'09120000008',email:'amir@example.test',role:'کاربر',status:'فعال',date:'۱۴۰۵/۰۷/۲۳'},
    {id:109,name:'پرنیا مرادی',phone:'09120000009',email:'parnia@example.test',role:'کاربر',status:'غیرفعال',date:'۱۴۰۵/۰۷/۲۴'},
    {id:110,name:'آرش دادگر',phone:'09120000010',email:'arash@example.test',role:'کاربر',status:'فعال',date:'۱۴۰۵/۰۷/۲۴'},
    {id:111,name:'یلدا کاظمی',phone:'09120000011',email:'yalda@example.test',role:'کاربر',status:'فعال',date:'۱۴۰۵/۰۷/۲۵'},
    {id:112,name:'فرزاد نیک‌پی',phone:'09120000012',email:'farzad@example.test',role:'کاربر',status:'در انتظار',date:'۱۴۰۵/۰۷/۲۵'}
  ];
  const storageKey='nebula-demo-users-v1';const settingsKey='nebula-demo-settings-v1';
  function storageGet(k){try{return JSON.parse(localStorage.getItem(k));}catch{return null;}}
  function storageSet(k,value){try{localStorage.setItem(k,JSON.stringify(value));}catch{/* private or restricted browsing: demo still works in memory */}}
  let users=storageGet(storageKey);if(!Array.isArray(users)||!users.every(x=>x&&typeof x.id==='number'&&typeof x.name==='string'))users=structuredClone(originalUsers);
  let settings={animation:true,compact:false,...(storageGet(settingsKey)||{})};

  // PUBLIC DEMO ACCOUNTS ONLY: client-side credentials provide no real security.
  const DEMO_ADMIN={username:'admin',password:'AdminDemo@2026'};
  const DEMO_SECRETARY_PASSWORD='DeskDemo@2026';
  const sessionKey='nebula-demo-session-v12';
  const secretaryKey='nebula-demo-secretaries-v12';
  const patientKey='nebula-demo-patients-v12';
  const appointmentKey='nebula-demo-appointments-v12';
  const doctorKey='nebula-demo-doctors-v12';
  const defaultSecretaries=[{id:1,name:'نگار حسینی',username:'secretary',status:'فعال'}];
  const defaultPatients=[{id:1,name:'علی رضایی',phone:'09120000031',note:'مراجع نمونه'}, {id:2,name:'رها احمدی',phone:'09120000032',note:'مراجع نمونه'}];
  const defaultDoctors=[{id:1,name:'دکتر آرزو موسوی',specialty:'عمومی',days:'شنبه، دوشنبه، چهارشنبه',hours:'۹:۰۰ تا ۱۵:۰۰'},{id:2,name:'دکتر مهراد شریفی',specialty:'مشاوره',days:'یکشنبه، سه‌شنبه',hours:'۱۰:۰۰ تا ۱۷:۰۰'}];
  const defaultAppointments=[{id:1,patientId:1,doctorId:1,date:'2026-11-02',time:'10:00',status:'رزرو شده',note:''},{id:2,patientId:2,doctorId:2,date:'2026-11-03',time:'12:30',status:'تأیید شده',note:''}];
  const loadArr=(key,defaults)=>{const val=storageGet(key);return Array.isArray(val)?val:structuredClone(defaults);};
  let secretaries=loadArr(secretaryKey,defaultSecretaries);
  let patients=loadArr(patientKey,defaultPatients);
  let doctors=loadArr(doctorKey,defaultDoctors);
  let appointments=loadArr(appointmentKey,defaultAppointments);
  let activeSession=null;
  try{activeSession=JSON.parse(sessionStorage.getItem(sessionKey)||'null');}catch{}
  function demoLogin(role,username,password){
    const valid=role==='admin'?username===DEMO_ADMIN.username&&password===DEMO_ADMIN.password:secretaries.some(x=>x.username===username&&x.status==='فعال')&&password===DEMO_SECRETARY_PASSWORD;
    if(!valid)return false;
    activeSession={role,username};try{sessionStorage.setItem(sessionKey,JSON.stringify(activeSession));}catch{}
    return true;
  }
  function demoLogout(){activeSession=null;try{sessionStorage.removeItem(sessionKey);}catch{}go('login');}
  function saveClinic(){storageSet(secretaryKey,secretaries);storageSet(patientKey,patients);storageSet(doctorKey,doctors);storageSet(appointmentKey,appointments);}
  function nextId(list){return Math.max(0,...list.map(x=>Number(x.id)||0))+1;}
  function nameBy(list,id){return list.find(x=>x.id===Number(id))?.name||'نامشخص';}
  function options(list,selected){return list.map(x=>`<option value="${x.id}" ${x.id===Number(selected)?'selected':''}>${esc(x.name)}</option>`).join('');}
  function demoCredentials(){return `<div class="callout" style="margin-top:16px;font-size:12px"><b>حساب‌های عمومی دمو (غیرامن):</b><br>مدیر: <code dir="ltr">admin / AdminDemo@2026</code><br>منشی: <code dir="ltr">secretary / DeskDemo@2026</code><br>برای اطلاعات واقعی بیماران استفاده نشود.</div>`;}
  function staffLogin(role){let admin=role==='admin';return `<div class="auth-panel glass"><span class="eyebrow">${admin?'ADMIN':'RECEPTION'} / DEMO</span><h1>ورود ${admin?'مدیر':'منشی'}</h1><p class="intro">برای مشاهده پنل ${admin?'مدیریت':'منشی'} از اطلاعات نمایشی زیر استفاده کنید.</p><form id="staff-login-form" data-role="${role}"><div class="field"><label for="staff-username">نام کاربری</label><div class="field-control">${icon('user')}<input id="staff-username" dir="ltr" required autocomplete="username" placeholder="${admin?'admin':'secretary'}"></div></div>${field('staff-password','رمز عبور','رمز آزمایشی','password',{autocomplete:'current-password'})}<button class="btn btn-primary btn-full" type="submit">${icon('arrow')} ورود به پنل ${admin?'مدیر':'منشی'}</button></form>${demoCredentials()}<p class="form-foot">${pageLink('ورود مدیر','admin/login')} · ${pageLink('ورود منشی','secretary/login')} · ${pageLink('صفحه اصلی','login')}</p></div>`;}
  function secretaryShell(section,body){const items=[['dashboard','داشبورد','dashboard'],['appointments','مدیریت نوبت‌ها','calendar'],['patients','مراجعان','users'],['doctors','برنامه پزشکان','clock']];return `${demoBanner()}<div class="overlay-mobile" id="mobile-overlay"></div><div class="admin-shell"><aside class="sidebar" id="sidebar">${brand()}<div><p class="sidebar-label">RECEPTION DESK</p><nav class="nav-list">${items.map(([k,t,i])=>`<a class="nav-link ${section===k?'active':''}" href="#/secretary/${k}">${icon(i)} ${t}</a>`).join('')}</nav></div><div class="side-bottom"><button type="button" class="nav-link demo-logout">${icon('logout')} خروج</button><div class="admin-profile"><span class="avatar">م</span><span><span class="name">${esc(activeSession?.username||'منشی')}</span><br><span class="role">Reception Demo</span></span></div></div></aside><main id="main" class="admin-main"><header class="admin-top"><div class="admin-top-left"><button id="mobile-menu" class="btn btn-ghost btn-icon mobile-toggle" type="button" aria-label="باز کردن منو">${icon('menu')}</button><span class="eyebrow">NEBULA / RECEPTION DESK</span></div><div class="admin-top-right"><span class="header-status"><span class="pulse"></span> DEMO MODE</span><button type="button" class="btn btn-ghost btn-sm demo-logout">خروج</button></div></header>${body}<footer class="public-footer" style="margin-top:45px">فقط داده ساختگی؛ اطلاعات واقعی بیماران وارد نشود.</footer></main></div>`;}
  function clinicTable(headers,rows){return `<div class="data-table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}">داده‌ای ثبت نشده است.</td></tr>`}</tbody></table></div>`;}
  function receptionistDashboard(){return secretaryShell('dashboard',`${heading('داشبورد منشی','مدیریت نوبت‌ها و مراجعان، با داده‌های ساختگی نسخه دمو.')}<section class="stats-grid">${stat('کل نوبت‌ها',appointments.length,'calendar','داده نمایشی')}${stat('مراجعان',patients.length,'users','داده نمایشی')}${stat('پزشکان',doctors.length,'clock','داده نمایشی')}${stat('نوبت‌های تأییدشده',appointments.filter(a=>a.status==='تأیید شده').length,'check','داده نمایشی')}</section><section class="panel glass" style="margin-top:20px"><div class="panel-heading"><h3>نوبت‌های ثبت‌شده</h3><a class="btn btn-primary btn-sm" href="#/secretary/appointments">مدیریت نوبت‌ها</a></div>${appointmentTable()}</section>`);}
  function appointmentTable(){return clinicTable(['مراجع','پزشک','تاریخ','ساعت','وضعیت','عملیات'],appointments.map(a=>`<tr><td>${esc(nameBy(patients,a.patientId))}</td><td>${esc(nameBy(doctors,a.doctorId))}</td><td dir="ltr">${esc(a.date)}</td><td dir="ltr">${esc(a.time)}</td><td><span class="chip">${esc(a.status)}</span></td><td><button class="btn btn-ghost btn-sm" data-appointment-edit="${a.id}">ویرایش</button> <button class="btn btn-ghost btn-sm" data-appointment-delete="${a.id}">حذف</button></td></tr>`));}
  function appointmentPage(role){const body=`${heading('مدیریت نوبت‌ها','ثبت، جابه‌جایی، تأیید و لغو نوبت‌های آزمایشی.',`<button class="btn btn-primary btn-sm" id="new-appointment">${icon('plus')} ثبت نوبت</button>`)}<section class="panel glass">${appointmentTable()}</section>`;return role==='admin'?adminShell('appointments',body):secretaryShell('appointments',body);}
  function patientTable(){return clinicTable(['نام','موبایل','یادداشت','عملیات'],patients.map(p=>`<tr><td>${esc(p.name)}</td><td dir="ltr">${esc(p.phone)}</td><td>${esc(p.note||'—')}</td><td><button class="btn btn-ghost btn-sm" data-patient-edit="${p.id}">ویرایش</button> <button class="btn btn-ghost btn-sm" data-patient-delete="${p.id}">حذف</button></td></tr>`));}
  function patientPage(role){const body=`${heading('مراجعان','فهرست مراجعان آزمایشی. اطلاعات سلامت واقعی وارد نکنید.',`<button class="btn btn-primary btn-sm" id="new-patient">${icon('plus')} افزودن مراجع</button>`)}<section class="panel glass">${patientTable()}</section>`;return role==='admin'?adminShell('patients',body):secretaryShell('patients',body);}
  function doctorTable(){return clinicTable(['پزشک','تخصص','روزهای حضور','ساعت حضور','عملیات'],doctors.map(d=>`<tr><td>${esc(d.name)}</td><td>${esc(d.specialty)}</td><td>${esc(d.days)}</td><td>${esc(d.hours)}</td><td><button class="btn btn-ghost btn-sm" data-doctor-edit="${d.id}">ویرایش</button> <button class="btn btn-ghost btn-sm" data-doctor-delete="${d.id}">حذف</button></td></tr>`));}
  function doctorPage(role){const body=`${heading('برنامه پزشکان','ثبت و اصلاح ساعت‌های حضور پزشکان در نسخه نمایشی.',`<button class="btn btn-primary btn-sm" id="new-doctor">${icon('plus')} افزودن پزشک</button>`)}<section class="panel glass">${doctorTable()}</section>`;return role==='admin'?adminShell('doctors',body):secretaryShell('doctors',body);}
  function secretaryPage(){return adminShell('secretaries',`${heading('مدیریت منشی‌ها','مدیر می‌تواند حساب‌های دمو منشی را اضافه، ویرایش یا غیرفعال کند.',`<button class="btn btn-primary btn-sm" id="new-secretary">${icon('plus')} افزودن منشی</button>`)}<section class="panel glass">${clinicTable(['نام','نام کاربری','وضعیت','عملیات'],secretaries.map(x=>`<tr><td>${esc(x.name)}</td><td dir="ltr">${esc(x.username)}</td><td>${esc(x.status)}</td><td><button class="btn btn-ghost btn-sm" data-secretary-edit="${x.id}">ویرایش</button> <button class="btn btn-ghost btn-sm" data-secretary-delete="${x.id}">حذف</button></td></tr>`))}${demoCredentials()}</section>`);}
  function genericInput(name,label,value='',type='text',required=true){return `<div class="field"><label for="${name}">${label}</label><div class="field-control"><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="120"></div></div>`;}
  function clinicModal(kind,id=0){const data=kind==='secretary'?secretaries:kind==='patient'?patients:kind==='doctor'?doctors:appointments;const obj=data.find(x=>x.id===Number(id))||{};const title={secretary:'منشی',patient:'مراجع',doctor:'پزشک',appointment:'نوبت'}[kind];let fields='';
    if(kind==='secretary')fields=genericInput('c-name','نام و نام خانوادگی',obj.name)+genericInput('c-username','نام کاربری (انگلیسی)',obj.username)+`<div class="field"><label>وضعیت</label><select id="c-status" class="select">${['فعال','غیرفعال'].map(v=>`<option ${obj.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="callout">رمز ورود همه منشی‌های نسخه دمو: <code dir="ltr">DeskDemo@2026</code> — رمز واقعی نیست.</div>`;
    if(kind==='patient')fields=genericInput('c-name','نام مراجع',obj.name)+genericInput('c-phone','تلفن نمونه',obj.phone)+genericInput('c-note','یادداشت عمومی و غیرحساس',obj.note,'text',false);
    if(kind==='doctor')fields=genericInput('c-name','نام پزشک',obj.name)+genericInput('c-specialty','تخصص',obj.specialty)+genericInput('c-days','روزهای حضور',obj.days)+genericInput('c-hours','ساعت حضور',obj.hours);
    if(kind==='appointment')fields=`<div class="field"><label>مراجع</label><select class="select" id="c-patient" required>${options(patients,obj.patientId)}</select></div><div class="field"><label>پزشک</label><select class="select" id="c-doctor" required>${options(doctors,obj.doctorId)}</select></div>${genericInput('c-date','تاریخ',obj.date||'', 'date')}${genericInput('c-time','ساعت',obj.time||'', 'time')}<div class="field"><label>وضعیت</label><select class="select" id="c-status">${['رزرو شده','تأیید شده','لغو شده','انجام شده'].map(v=>`<option ${obj.status===v?'selected':''}>${v}</option>`).join('')}</select></div>${genericInput('c-note','یادداشت غیرحساس',obj.note||'','text',false)}`;
    showModal(`<header><h2 id="modal-title">${id?'ویرایش':'افزودن'} ${title} (دمو)</h2><button type="button" id="modal-close" class="btn btn-ghost btn-icon">${icon('close')}</button></header><form id="clinic-form" data-kind="${kind}" data-id="${id}">${fields}<footer><button type="button" id="cancel-modal" class="btn btn-ghost">انصراف</button><button type="submit" class="btn btn-primary">ذخیره</button></footer></form>`);
  }
  function saveClinicForm(f){const kind=f.dataset.kind,id=Number(f.dataset.id);let list=kind==='secretary'?secretaries:kind==='patient'?patients:kind==='doctor'?doctors:appointments;let entry={};const get=id=>$('#'+id)?.value.trim()||'';
    if(kind==='secretary'){entry={name:get('c-name'),username:get('c-username'),status:get('c-status')};if(!/^[a-z][a-z0-9_-]{2,29}$/i.test(entry.username)){toast('نام کاربری باید ۳ تا ۳۰ حرف انگلیسی یا عدد باشد.');return;}if(secretaries.some(x=>x.username===entry.username&&x.id!==id)){toast('نام کاربری تکراری است.');return;}}
    if(kind==='patient'){entry={name:get('c-name'),phone:get('c-phone'),note:get('c-note')};if(!validPhone(entry.phone)){toast('موبایل نمونه معتبر نیست.');return;}}
    if(kind==='doctor')entry={name:get('c-name'),specialty:get('c-specialty'),days:get('c-days'),hours:get('c-hours')};
    if(kind==='appointment'){entry={patientId:Number(get('c-patient')),doctorId:Number(get('c-doctor')),date:get('c-date'),time:get('c-time'),status:get('c-status'),note:get('c-note')};if(!patients.some(x=>x.id===entry.patientId)||!doctors.some(x=>x.id===entry.doctorId)){toast('مراجع و پزشک را انتخاب کنید.');return;}if(appointments.some(x=>x.id!==id&&x.doctorId===entry.doctorId&&x.date===entry.date&&x.time===entry.time&&x.status!=='لغو شده'&&entry.status!=='لغو شده')){toast('این ساعت برای پزشک مورد نظر قبلاً رزرو شده است.');return;}}
    if(Object.entries(entry).some(([k,v])=>typeof v==='string'&&!v&&!['note'].includes(k))){toast('فیلدهای لازم را تکمیل کنید.');return;}
    if(id){const old=list.find(x=>x.id===id);if(old)Object.assign(old,entry);}else{list.push({id:nextId(list),...entry});}saveClinic();closeModal();render();toast('اطلاعات نمایشی ذخیره شد.');
  }
  function clinicDelete(kind,id){let list=kind==='secretary'?secretaries:kind==='patient'?patients:kind==='doctor'?doctors:appointments;const record=list.find(x=>x.id===Number(id));if(!record)return;if(kind==='patient'&&appointments.some(a=>a.patientId===record.id)){toast('ابتدا نوبت‌های این مراجع را حذف کنید.');return;}if(kind==='doctor'&&appointments.some(a=>a.doctorId===record.id)){toast('ابتدا نوبت‌های این پزشک را حذف کنید.');return;}if(!confirm('رکورد نمونه حذف شود؟'))return;const idx=list.indexOf(record);list.splice(idx,1);saveClinic();render();toast('رکورد نمایشی حذف شد.');}

  const state={search:'',status:'همه وضعیت‌ها',role:'همه نقش‌ها',page:1,limit:6,sort:'new',activityFilter:'همه',otpPhone:'',demoRole:'کاربر'};
  function saveUsers(){storageSet(storageKey,users);}
  function toast(message){const stack=$('#toast-stack');const el=document.createElement('div');el.className='toast';el.textContent=message;stack.append(el);setTimeout(()=>el.remove(),3700);}
  function route(){const raw=decodeURIComponent((location.hash||'#/login').slice(2));return raw||'login';}
  function go(to){location.hash='#/'+to;}
  function updateMotion(){document.body.classList.toggle('motion-off',!settings.animation);window.nebulaSpace?.refresh();}
  function publicHeader(){return `<header class="container public-header">${brand()}<div class="header-actions"><span class="header-status"><span class="pulse"></span> INTERACTIVE UI DEMO</span>${pageLink('ورود مدیر','admin/login','btn btn-ghost btn-sm')} ${pageLink('ورود منشی','secretary/login','btn btn-ghost btn-sm')}</div></header>`;}
  function visual(){return `<div class="auth-side"><div class="visual-scene" id="tilt-scene" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="orbit three"></div><div class="core-glow">${icon('logo','lg')}</div><div class="visual-dot d1"></div><div class="visual-dot d2"></div><div class="visual-dot d3"></div></div><div class="side-caption"><span class="eyebrow">BEYOND ORDINARY ACCESS</span><h2>دروازه‌ای به <span class="text-gradient">دنیای آینده</span></h2><p>تجربه‌ای متفاوت از مدیریت هویت دیجیتال در فضایی سه‌بعدی و پویا</p></div><div class="telemetry"><span>NEBULA / N-01</span><span>34.89° N · 82.02° W</span><span>ALT: 418 KM</span></div><span class="scroller">${icon('chevron','small')} برای کشف بیشتر اسکرول کنید</span></div>`;}
  function field(id,label,placeholder,type='text',opts={}){const required=opts.required===false?'':'required';return `<div class="field"><label for="${id}">${label}</label><div class="field-control">${icon(opts.icon||(type==='password'?'lock':type==='email'?'mail':type==='tel'?'phone':'user'))}<input id="${id}" name="${id}" type="${type}" placeholder="${esc(placeholder)}" ${required} ${opts.dir?`dir="${opts.dir}"`:''} ${opts.autocomplete?`autocomplete="${opts.autocomplete}"`:''} ${opts.minlength?`minlength="${opts.minlength}"`:''} class="${type==='password'?'with-extra':''}" ${type==='tel'?'inputmode="tel"':''} maxlength="${opts.maxlength||128}">${type==='password'?`<button class="toggle-pass" type="button" aria-label="نمایش رمز عبور" data-toggle-pass="${id}">${icon('eye','small')}</button>`:''}</div><div class="field-error" id="${id}-error" role="alert"></div></div>`;}
  function loginForm(admin=false){return `<div class="auth-panel glass"><span class="eyebrow">${admin?'ADMINISTRATOR CHANNEL':'NEBULA IDENTITY PROTOCOL'}</span><h1>${admin?'ورود به مرکز فرماندهی':'خوش آمدید'}</h1><p class="intro">${admin?'نمایش رابط ورود مدیر؛ این قالب احراز هویت واقعی انجام نمی‌دهد.':'برای ورود به دنیای خود، اطلاعات حساب کاربری را وارد کنید.'}</p><div class="tab-switch"><a class="active" href="#/${admin?'admin/login':'login'}">ورود با رمز عبور</a><a href="#/otp">ورود با کد تأیید</a></div><form id="login-form" novalidate data-admin="${admin}">${field('loginPhone','شماره موبایل','0912 345 6789','tel',{dir:'ltr',autocomplete:'tel',maxlength:15})}${field('loginPassword','رمز عبور','رمز عبور خود را وارد کنید','password',{minlength:8,autocomplete:'current-password'})}<div class="form-row"><label class="check-label"><input type="checkbox" id="remember" checked> مرا به خاطر بسپار</label>${pageLink('فراموشی رمز عبور؟','forgot')}</div><button class="btn btn-primary btn-full" type="submit">${icon('arrow')} ${admin?'مشاهده داشبورد نمایشی':'نمایش ورود به سامانه'}</button></form><p class="form-foot">${admin?`${pageLink('بازگشت به ورود کاربران','login')}`:`حساب ندارید؟ ${pageLink('ایجاد حساب جدید','register')}`}</p><div class="divider-label">نمایش محیط بدون احراز هویت</div><a class="btn btn-ghost btn-full" href="#/admin/dashboard">${icon('dashboard','small')} ورود برای مشاهده پنل مدیریت</a></div>`;}
  function registerForm(){return `<div class="auth-panel glass"><span class="eyebrow">JOIN NEBULA ACCESS</span><h1>ساخت حساب کاربری</h1><p class="intro">اطلاعات خود را برای مشاهده فرآیند ثبت‌نام نمایشی وارد کنید.</p><form id="register-form" novalidate><div class="form-grid">${field('first','نام','نام شما')}${field('last','نام خانوادگی','نام خانوادگی شما')}</div>${field('regPhone','شماره موبایل','0912 345 6789','tel',{dir:'ltr',maxlength:15})}${field('email','ایمیل (اختیاری)','name@example.com','email',{required:false,dir:'ltr'})}${field('password','رمز عبور','حداقل ۸ نویسه','password',{minlength:8})}<div class="strength" aria-label="قدرت رمز عبور"><span id="strength-fill"></span></div><p class="field-hint" id="strength-label" style="margin:3px 0 13px;color:var(--muted);font-size:11px">قدرت رمز عبور</p>${field('confirm','تکرار رمز عبور','تکرار رمز عبور','password')}<label class="check-label" style="margin-bottom:19px"><input id="agree" type="checkbox" required> قوانین و شرایط استفاده آزمایشی را می‌پذیرم</label><button type="submit" class="btn btn-primary btn-full">${icon('plus')} ایجاد حساب نمایشی</button></form><p class="form-foot">قبلاً ثبت‌نام کرده‌اید؟ ${pageLink('ورود به حساب','login')}</p></div>`;}
  function otpForm(){return `<div class="auth-panel glass"><span class="eyebrow">DEMO VERIFICATION</span><h1>تأیید شماره موبایل</h1><p class="intro">در این نسخه هیچ پیامکی ارسال نمی‌شود. برای مشاهده جریان تأیید، هر کد ۶ رقمی را وارد کنید.</p><div class="callout" role="note">${icon('info','small')} OTP فقط شبیه‌سازی شده است و نباید برای احراز هویت واقعی استفاده شود.</div><form id="otp-form"><div class="otp-row" aria-label="کد شش رقمی">${Array.from({length:6},(_,i)=>`<input inputmode="numeric" type="text" class="otp-box" maxlength="1" aria-label="رقم ${i+1}" autocomplete="off" pattern="[0-9۰-۹]">`).join('')}</div><button class="btn btn-primary btn-full" type="submit">${icon('check')} تأیید نمایشی و ورود</button></form><div class="form-row" style="margin-top:19px"><button type="button" class="link" style="border:0;background:none" id="resend-code">ارسال مجدد کد نمایشی</button>${pageLink('ویرایش شماره','login')}</div></div>`;}
  function forgotForm(){return `<div class="auth-panel glass"><span class="eyebrow">ACCOUNT RECOVERY</span><h1>بازیابی رمز عبور</h1><p class="intro">فرآیند بازیابی تنها برای نمایش رابط کاربری است و پیامک ارسال نمی‌شود.</p><form id="forgot-form">${field('forgotPhone','شماره موبایل','0912 345 6789','tel',{dir:'ltr',maxlength:15})}<button class="btn btn-primary btn-full" type="submit">${icon('arrow')} ادامه بازیابی نمایشی</button></form><p class="form-foot">${pageLink('بازگشت به ورود','login')}</p></div>`;}
  function resetForm(){return `<div class="auth-panel glass"><span class="eyebrow">RESET PASSWORD / DEMO</span><h1>تعیین رمز عبور جدید</h1><p class="intro">این فرم فقط نمایشی است و هیچ رمز عبوری را ذخیره یا ارسال نمی‌کند.</p><form id="reset-form">${field('newPassword','رمز عبور جدید','حداقل ۸ نویسه','password',{minlength:8})}${field('newConfirm','تکرار رمز عبور','رمز عبور جدید را تکرار کنید','password')}<button class="btn btn-primary btn-full" type="submit">${icon('check')} تأیید بازنشانی نمایشی</button></form></div>`;}
  function publicFooter(){return `<footer class="container public-footer"><span>© Nebula Access Pro — نسخه نمایشی رابط کاربری</span><span>Persian / RTL · 100% Static · No Backend Required</span></footer>`;}
  function story(){return `<div class="divider"></div><section class="container story-section"><div class="story-head reveal"><span class="eyebrow">BUILT FOR THE NEXT ERA</span><h2>کشف یک تجربه <span class="text-gradient">متفاوت</span></h2><p>طراحی دقیق جزئیات، حرکت‌های نرم و هماهنگی کامل با زبان فارسی.</p></div><div class="story-grid"><article class="feature glass reveal"><div class="feature-icon">${icon('shield','lg')}</div><h3>رابط امنیت‌محور</h3><p>صفحات ورود، ثبت‌نام و بازیابی با طراحی بصری مناسب برای اتصال به سامانه امن احراز هویت.</p></article><article class="feature glass reveal"><div class="feature-icon">${icon('dashboard','lg')}</div><h3>داشبورد کاربردی</h3><p>نمایش اطلاعات، جستجو، مدیریت کاربران و گزارش‌های دیداری تعاملی در حالت نمایشی.</p></article><article class="feature glass reveal"><div class="feature-icon">${icon('globe','lg')}</div><h3>فضای سه‌بعدی پویا</h3><p>ذرات ستاره‌ای مبتنی بر عمق، واکنش به حرکت موس و لایه‌های پارالاکس همراه با اسکرول.</p></article></div></section><section class="container story-section story-highlight"><div class="reveal"><span class="eyebrow">INTERACTIVE DESIGN SYSTEM</span><h2>هر حرکت، <span class="text-gradient">یک داستان تازه</span></h2><p class="muted" style="margin:14px 0 25px;max-width:500px">با هر اسکرول، اجزای صفحه به‌آرامی آشکار می‌شوند. ستاره‌ها در عمق فضا حرکت می‌کنند و سطح کارت‌ها به تغییر موقعیت اشاره‌گر پاسخ می‌دهد.</p>${pageLink(`${icon('dashboard')} دیدن داشبورد تعاملی`,'admin/dashboard','btn btn-ghost')}</div><div class="mini-visual reveal"><div class="ring-visual"></div></div></section><section class="container story-cta glass reveal"><span class="eyebrow">YOUR UNIVERSE AWAITS</span><h2 style="margin:12px 0">آماده ورود به دنیای جدید هستید؟</h2><p class="muted" style="margin-bottom:23px">تجربه طراحی و تعامل در یک قالب مدرن، مستقل و کاملاً راست‌چین</p>${pageLink(`${icon('arrow')} ورود به حساب کاربری`,'login','btn btn-primary')}</section>`;}
  function publicPage(kind){let content=(kind==='admin/login'||kind==='secretary/login')?staffLogin(kind==='admin/login'?'admin':'secretary'):kind==='register'?registerForm():kind==='otp'?otpForm():kind==='forgot'?forgotForm():kind==='reset'?resetForm():loginForm(kind==='admin/login');const long=kind==='login';return `${demoBanner()}<div class="auth-page">${publicHeader()}<main id="main"><div class="container auth-hero">${content}${visual()}</div>${long?story():''}</main>${publicFooter()}</div>`;}
  const routeNames={secretaries:'مدیریت منشی‌ها',appointments:'نوبت‌ها',patients:'مراجعان',doctors:'برنامه پزشکان',dashboard:'داشبورد مدیریت',users:'مدیریت کاربران',analytics:'گزارش‌های آماری',activity:'فعالیت‌های سیستم',settings:'تنظیمات',profile:'پروفایل مدیر'};
  function adminShell(section,body){return `${demoBanner()}<div class="overlay-mobile" id="mobile-overlay"></div><div class="admin-shell"><aside class="sidebar" id="sidebar" aria-label="منوی مدیریت">${brand()}<div><p class="sidebar-label">MAIN NAVIGATION</p><nav class="nav-list" aria-label="ناوبری اصلی">${navItems.map(([key,text,ic])=>`<a href="#/admin/${key}" class="nav-link ${section===key?'active':''}" ${section===key?'aria-current="page"':''}>${icon(ic)} ${text}</a>`).join('')}</nav></div><div class="side-bottom"><p class="sidebar-label">ACCOUNT</p><div class="nav-list"><a href="#/login" class="nav-link">${icon('logout')} خروج از نسخه نمایشی</a></div><div class="admin-profile"><span class="avatar">نـ</span><span><span class="name">مدیر نمونه</span><br><span class="role">Demo Administrator</span></span></div></div></aside><main id="main" class="admin-main"><header class="admin-top"><div class="admin-top-left"><button id="mobile-menu" class="btn btn-ghost btn-icon mobile-toggle" type="button" aria-label="باز کردن منو">${icon('menu')}</button><span class="eyebrow">NEBULA / CONTROL CENTER</span></div><div class="admin-top-right"><span class="header-status"><span class="pulse"></span> DEMO MODE</span><a class="btn btn-ghost btn-icon" href="#/admin/activity" aria-label="فعالیت‌ها">${icon('bell')}</a><a href="#/admin/profile" class="avatar" aria-label="پروفایل مدیر">نـ</a></div></header>${body}<footer class="public-footer" style="margin-top:45px"><span>Nebula Access Pro / Admin Demo</span><span>اطلاعات این بخش ساختگی هستند و در مرورگر ذخیره می‌شوند.</span></footer></main></div>`;}
  function heading(title,desc,action=''){return `<div class="page-heading"><div><span class="eyebrow">NEBULA CONTROL PANEL</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
  function stat(title,value,ic,delta){return `<article class="stat-card glass"><div class="stat-icon">${icon(ic)}</div><div class="num" dir="ltr" style="text-align:right">${Number(value).toLocaleString('fa-IR')}</div><div class="caption">${title}</div><div class="stat-sub">${delta}</div><svg class="stat-spark" viewBox="0 0 110 50" aria-hidden="true"><path d="M0 43 18 34 36 41 53 25 68 29 83 15 110 3" fill="none" stroke="#00d9ff" stroke-width="2"/><path d="M0 43 18 34 36 41 53 25 68 29 83 15 110 3V50H0Z" fill="#00d9ff" fill-opacity=".09"/></svg></article>`;}
  function graph(){return `<div class="chart-area"><svg viewBox="0 0 650 230" preserveAspectRatio="none" role="img" aria-label="نمودار نمایشی رشد کاربران طی هفت ماه"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#00d9ff" stop-opacity=".27"/><stop offset="1" stop-color="#00d9ff" stop-opacity="0"/></linearGradient></defs>${[35,78,121,164,207].map(y=>`<line x1="0" y1="${y}" x2="650" y2="${y}" stroke="#26405e" stroke-dasharray="4 6"/>`).join('')}<path d="M0 202 C70 195 85 155 130 166 S210 170 260 123 S340 130 390 95 S480 104 525 62 S610 78 650 18 L650 230 H0Z" fill="url(#chartFill)"/><path d="M0 202 C70 195 85 155 130 166 S210 170 260 123 S340 130 390 95 S480 104 525 62 S610 78 650 18" fill="none" stroke="#00d9ff" stroke-width="3.5" stroke-linecap="round"/></svg></div><div class="axis-labels"><span>فروردین</span><span>اردیبهشت</span><span>خرداد</span><span>تیر</span><span>مرداد</span><span>شهریور</span><span>مهر</span></div>`;}
  const events=[['ثبت‌نام کاربر جدید','آوا کیانی یک حساب نمایشی ایجاد کرد.','۱۰ دقیقه پیش','users'],['به‌روزرسانی اطلاعات','مشخصات پروفایل نمونه ویرایش شد.','۲۸ دقیقه پیش','edit'],['ورود مدیر به محیط نمایشی','صفحه داشبورد از مسیر پیش‌نمایش باز شد.','۱ ساعت پیش','shield'],['تغییر وضعیت حساب','وضعیت یک حساب نمایشی تغییر کرد.','۳ ساعت پیش','activity'],['گزارش عملکرد','آمار هفتگی نمونه آماده نمایش شد.','دیروز','chart']];
  function eventList(count=5){return events.slice(0,count).map(([title,desc,time,ic])=>`<div class="event-item"><span class="event-icon">${icon(ic,'small')}</span><div class="text"><strong>${title}</strong><p>${desc}</p></div><small class="muted">${time}</small></div>`).join('');}
  function dashboard(){let active=users.filter(u=>u.status==='فعال').length;return adminShell('dashboard',`${heading('داشبورد مدیریت','به مرکز فرماندهی خوش آمدید؛ وضعیت نمایشی سامانه را از اینجا مشاهده کنید.',`<a class="btn btn-primary btn-sm" href="#/admin/users">${icon('users','small')} مدیریت کاربران</a>`)}<section class="dashboard-hero"><div><span class="eyebrow">CONTROL CENTER / ONLINE</span><h2>سلام، به <span class="text-gradient">Nebula Access</span> خوش آمدید</h2><p>تمام بخش‌های این داشبورد برای پیش‌نمایش محصول تعاملی هستند.</p><div class="space-brief"><span class="chip">${icon('globe','small')} رابط فارسی و RTL</span><span class="chip green">${icon('check','small')} نسخه نمایشی فعال</span></div></div><div class="hologram" aria-hidden="true"><span class="ring"></span><span class="ring"></span>${icon('logo','lg')}</div></section><section class="stats-grid" aria-label="آمار نمونه">${stat('تعداد کل کاربران',users.length,'users','اطلاعات نمونه')}${stat('کاربران فعال',active,'shield','قابل ویرایش در دمو')}${stat('ثبت‌نام‌های این ماه',Math.min(users.length,9),'plus','آمار آزمایشی')}${stat('ورودهای امروز',28,'activity','داده فرضی')}</section><div class="dashboard-grid"><section class="panel glass"><div class="panel-heading"><div><h3>روند رشد کاربران</h3><p>اطلاعات نمونه / هفت ماه اخیر</p></div><span class="chip green">+ ۲۴.۸٪</span></div>${graph()}</section><section class="panel glass"><div class="panel-heading"><div><h3>فعالیت‌های اخیر</h3><p>رویدادهای نمونه سامانه</p></div><a class="link tiny" href="#/admin/activity">مشاهده همه</a></div>${eventList(4)}</section></div><section class="panel glass" style="margin-top:18px"><div class="panel-heading"><div><h3>آخرین کاربران</h3><p>نمایش آخرین رکوردهای نمونه</p></div><a class="btn btn-ghost btn-sm" href="#/admin/users">همه کاربران ${icon('arrow','small')}</a></div>${userTable(users.slice(-4).reverse(),false)}</section>`);}
  function userTable(list,actions=true){if(!list.length)return `<div class="empty">${icon('users','lg')} موردی مطابق جستجو پیدا نشد.</div>`;return `<div class="data-table-wrap"><table class="data-table"><thead><tr><th scope="col">کاربر</th><th scope="col">شماره موبایل</th><th scope="col">نقش</th><th scope="col">وضعیت</th><th scope="col">تاریخ عضویت</th><th scope="col">عملیات</th></tr></thead><tbody>${list.map(u=>`<tr><td><div class="user-name"><span class="user-avatar">${esc(u.name.slice(0,1))}</span><span><strong>${esc(u.name)}</strong><br><small class="muted" dir="ltr">${esc(u.email)}</small></span></div></td><td class="mono">${esc(u.phone)}</td><td>${esc(u.role)}</td><td><span class="chip ${u.status==='فعال'?'green':u.status==='غیرفعال'?'red':'yellow'}">${esc(u.status)}</span></td><td>${esc(u.date)}</td><td><div class="action-row"><button type="button" aria-label="مشاهده و ویرایش ${esc(u.name)}" data-edit="${u.id}">${icon('edit','small')}</button>${actions?`<button type="button" aria-label="حذف ${esc(u.name)}" data-delete="${u.id}">${icon('trash','small')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`;}
  function filteredUsers(){let list=users.filter(u=>(`${u.name} ${u.phone} ${u.email}`).toLowerCase().includes(state.search.toLowerCase())&&(state.status==='همه وضعیت‌ها'||u.status===state.status)&&(state.role==='همه نقش‌ها'||u.role===state.role));if(state.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'fa'));if(state.sort==='new')list.sort((a,b)=>b.id-a.id);return list;}
  function userManagement(){const list=filteredUsers();const totalPages=Math.max(1,Math.ceil(list.length/state.limit));state.page=Math.min(state.page,totalPages);const begin=(state.page-1)*state.limit;const slice=list.slice(begin,begin+state.limit);return adminShell('users',`${heading('مدیریت کاربران','جستجو، فیلتر و ویرایش اطلاعات نمونه کاربران در مرورگر.',`<button type="button" id="add-user" class="btn btn-primary btn-sm">${icon('plus','small')} افزودن کاربر</button>`)}<div class="callout warning" style="margin-bottom:18px">این کاربران ساختگی هستند و ویرایش‌ها تنها در حافظه مرورگر شما ذخیره می‌شوند. برای مدیریت کاربران واقعی باید بک‌اند امن متصل شود.</div><section class="panel glass"><div class="table-toolbar"><div class="filters"><input id="user-search" type="search" aria-label="جستجوی کاربران" placeholder="جستجوی نام، موبایل یا ایمیل..." value="${esc(state.search)}"><select id="status-filter" aria-label="فیلتر وضعیت">${['همه وضعیت‌ها','فعال','غیرفعال','در انتظار'].map(x=>`<option ${state.status===x?'selected':''}>${x}</option>`).join('')}</select><select id="role-filter" aria-label="فیلتر نقش">${['همه نقش‌ها','مدیر','کاربر'].map(x=>`<option ${state.role===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="filters"><select id="sort-filter" aria-label="مرتب‌سازی"><option value="new" ${state.sort==='new'?'selected':''}>جدیدترین</option><option value="name" ${state.sort==='name'?'selected':''}>بر اساس نام</option></select><button class="btn btn-ghost btn-sm" id="export-csv" type="button">${icon('download','small')} CSV</button></div></div><div id="user-results">${userTable(slice)}${pagination(list.length,totalPages,begin)}</div></section>`);}
  function pagination(total,pages,begin){return `<div class="table-end"><span>${total?`${(begin+1).toLocaleString('fa-IR')} تا ${Math.min(begin+state.limit,total).toLocaleString('fa-IR')} از ${total.toLocaleString('fa-IR')}`:'۰ نتیجه'}</span><div class="page-controls">${Array.from({length:pages},(_,i)=>`<button type="button" class="${i+1===state.page?'active':''}" aria-label="صفحه ${i+1}" data-page="${i+1}" ${i+1===state.page?'aria-current="page"':''}>${(i+1).toLocaleString('fa-IR')}</button>`).join('')}</div></div>`;}
  function refreshUsers(){const target=$('#user-results');if(!target)return;let list=filteredUsers();let pages=Math.max(1,Math.ceil(list.length/state.limit));state.page=Math.min(state.page,pages);let begin=(state.page-1)*state.limit;target.innerHTML=userTable(list.slice(begin,begin+state.limit))+pagination(list.length,pages,begin);}
  function analytics(){const bars=[32,54,48,67,59,78,93,81,103,120,112,145];return adminShell('analytics',`${heading('گزارش‌ها و تحلیل‌ها','مرکز مشاهده نمودارها و شاخص‌های نمونه عملکرد.',`<button class="btn btn-ghost btn-sm" id="export-report">${icon('download','small')} خروجی گزارش نمایشی</button>`)}<section class="stats-grid">${stat('کاربران ثبت‌شده',users.length,'users','بروزرسانی در دمو')}${stat('نرخ رشد فرضی',24,'chart','درصد')}${stat('میانگین فعالیت',67,'activity','درصد فرضی')}${stat('رویدادهای ثبت شده',428,'clock','داده نمونه')}</section><div class="dashboard-grid"><section class="panel glass"><div class="panel-heading"><div><h3>نمودار رشد ماهانه</h3><p>اطلاعات شبیه‌سازی‌شده</p></div><span class="chip">۱۲ ماه</span></div><div class="bar-chart">${bars.map((h,i)=>`<div class="bar-col"><span class="bar" title="شاخص نمونه ${h}" style="height:${Math.round(h/145*100)}%"></span><small>${(i+1).toLocaleString('fa-IR')}</small></div>`).join('')}</div></section><section class="panel glass"><div class="panel-heading"><h3>ترکیب وضعیت کاربران</h3></div>${['فعال','غیرفعال','در انتظار'].map((s,i)=>{let c=users.filter(u=>u.status===s).length;return `<div style="margin:18px 0"><div class="simple-row" style="border:0;padding:0 0 7px"><strong>${s}</strong><span class="muted">${c.toLocaleString('fa-IR')} کاربر</span></div><div style="height:9px;background:#162b45;border-radius:20px;overflow:hidden"><div style="width:${users.length?c/users.length*100:0}%;height:100%;border-radius:20px;background:${['#00d9ff','#6989a9','#ffbf74'][i]}"></div></div></div>`;}).join('')}</section></div><section class="panel glass" style="margin-top:18px"><div class="panel-heading"><h3>روند بلندمدت (نمونه)</h3><span class="chip">ماهانه</span></div>${graph()}</section>`);}
  function activity(){const items=events.filter(e=>state.activityFilter==='همه'||(state.activityFilter==='ثبت‌نام'?e[3]==='users':e[3]!=='users'));return adminShell('activity',`${heading('فعالیت‌های سیستم','فهرست رویدادهای نمونه برای نمایش تجربه کاربری.')}<section class="panel glass"><div class="table-toolbar"><h3>تاریخچه فعالیت‌ها</h3><select id="activity-filter" class="select" style="width:180px;min-height:40px;padding:8px" aria-label="فیلتر رویدادها"><option ${state.activityFilter==='همه'?'selected':''}>همه</option><option ${state.activityFilter==='ثبت‌نام'?'selected':''}>ثبت‌نام</option><option ${state.activityFilter==='سایر فعالیت‌ها'?'selected':''}>سایر فعالیت‌ها</option></select></div>${items.map(([t,d,time,ic])=>`<article class="activity-card light-glass"><div style="display:flex;align-items:center;gap:12px"><span class="event-icon">${icon(ic)}</span><div><h3>${t}</h3><p>${d}</p></div></div><span class="tiny muted">${time}</span></article>`).join('')||'<div class="empty">رویدادی یافت نشد.</div>'}</section>`);}
  function settingsPage(){return adminShell('settings',`${heading('تنظیمات سامانه','شخصی‌سازی تجربه بصری نسخه نمایشی.')}<div class="settings-grid"><section class="panel glass"><div class="panel-heading"><h3>تنظیمات ظاهری</h3></div><div class="setting-row"><div><strong>انیمیشن‌های کهکشانی</strong><p>حرکت ستارگان، مدارها و جلوه‌های بصری</p></div><label class="switch"><input type="checkbox" id="setting-motion" ${settings.animation?'checked':''} aria-label="فعال کردن انیمیشن‌ها"></label></div><div class="setting-row"><div><strong>نمایش فشرده</strong><p>آزمایش فاصله‌گذاری کمتر در بخش مدیریت</p></div><label class="switch"><input type="checkbox" id="setting-compact" ${settings.compact?'checked':''} aria-label="نمایش فشرده"></label></div><div class="setting-row"><div><strong>زبان رابط کاربری</strong><p>فارسی / راست‌چین</p></div><span class="chip">FA / RTL</span></div></section><section class="panel glass"><div class="panel-heading"><h3>داده‌های نمونه</h3></div><p class="muted" style="font-size:12px;margin-bottom:20px">برای نمایش قابلیت‌های قالب، تغییرات کاربران روی همین دستگاه در localStorage نگهداری می‌شود. هیچ اطلاعاتی به سرور ارسال نمی‌شود.</p><button id="reset-data" class="btn btn-danger">${icon('refresh','small')} بازنشانی داده‌های نمایشی</button><div class="callout warning" style="margin-top:18px"><strong>امنیت:</strong> این نسخه سیستم احراز هویت ندارد. قبل از استفاده واقعی باید احراز هویت و مجوزهای دسترسی را در سرور اجرا کنید.</div></section></div>`);}
  function profile(){return adminShell('profile',`${heading('پروفایل مدیر','نمایش کارت حساب کاربری و تنظیمات نمونه پروفایل.')}<div class="layout-two"><section class="panel glass"><div style="display:flex;align-items:center;gap:15px;margin-bottom:25px"><span class="avatar" style="width:66px;height:66px;font-size:21px">نـ</span><div><h2>مدیر نمونه</h2><p class="muted tiny">Demo Administrator</p></div></div><form id="profile-form"><div class="form-grid">${field('profileFirst','نام','مدیر')}${field('profileLast','نام خانوادگی','نمونه')}</div>${field('profileEmail','ایمیل','demo@example.test','email',{dir:'ltr'})}<button class="btn btn-primary" type="submit">${icon('check','small')} ذخیره نمونه</button></form></section><section class="panel glass"><div class="panel-heading"><h3>اطلاعات حساب</h3></div><div class="simple-list"><div class="simple-row"><span class="muted">نقش</span><span class="chip">مدیر نمایشی</span></div><div class="simple-row"><span class="muted">نوع پروژه</span><span>UI Template</span></div><div class="simple-row"><span class="muted">سطح امنیت</span><span class="chip yellow">بدون بک‌اند</span></div></div><div class="callout" style="margin-top:24px">این فرم صرفاً شبیه‌سازی رابط کاربری است. پروفایل واقعی باید به API امن متصل شود.</div></section></div>`);}
  function showModal(inner){closeModal();const root=document.createElement('div');root.className='modal-backdrop';root.id='modal-layer';root.innerHTML=`<section class="modal glass" role="dialog" aria-modal="true" aria-labelledby="modal-title">${inner}</section>`;document.body.appendChild(root);root.addEventListener('mousedown',e=>{if(e.target===root)closeModal();});$('#modal-close',root)?.focus();}
  function closeModal(){$('#modal-layer')?.remove();}
  function editUser(id){const u=users.find(x=>x.id===Number(id));const isNew=!u;const record=u||{id:0,name:'',phone:'',email:'',role:'کاربر',status:'فعال'};showModal(`<header><div><span class="eyebrow">USER MANAGEMENT / DEMO</span><h2 id="modal-title">${isNew?'افزودن کاربر نمونه':'ویرایش کاربر نمونه'}</h2></div><button class="btn btn-ghost btn-icon" type="button" id="modal-close" aria-label="بستن">${icon('close')}</button></header><form id="edit-user-form" data-id="${record.id}"><div class="form-grid"><div class="field"><label for="edit-name">نام و نام خانوادگی</label><div class="field-control">${icon('user')}<input id="edit-name" required maxlength="60" value="${esc(record.name)}" placeholder="نام و نام خانوادگی"></div></div><div class="field"><label for="edit-phone">شماره موبایل</label><div class="field-control">${icon('phone')}<input id="edit-phone" dir="ltr" required value="${esc(record.phone)}" placeholder="09123456789" maxlength="15"></div></div></div><div class="field"><label for="edit-email">ایمیل</label><div class="field-control">${icon('mail')}<input id="edit-email" type="email" required dir="ltr" value="${esc(record.email)}" placeholder="user@example.test"></div></div><div class="form-grid"><div class="field"><label for="edit-role">نقش نمایشی</label><div class="field-control"><select id="edit-role"><option ${record.role==='کاربر'?'selected':''}>کاربر</option><option ${record.role==='مدیر'?'selected':''}>مدیر</option></select></div></div><div class="field"><label for="edit-status">وضعیت</label><div class="field-control"><select id="edit-status">${['فعال','غیرفعال','در انتظار'].map(s=>`<option ${record.status===s?'selected':''}>${s}</option>`).join('')}</select></div></div></div><div class="callout warning">تغییر نقش و وضعیت فقط نمایشی است و هیچ دسترسی واقعی ایجاد نمی‌کند.</div><footer><button type="button" class="btn btn-ghost" id="cancel-modal">انصراف</button><button type="submit" class="btn btn-primary">${icon('check','small')} ذخیره تغییرات نمونه</button></footer></form>`);}
  function deleteUser(id){const u=users.find(x=>x.id===Number(id));if(!u)return;showModal(`<header><h2 id="modal-title">حذف کاربر نمونه</h2><button class="btn btn-ghost btn-icon" id="modal-close" aria-label="بستن">${icon('close')}</button></header><p>آیا از حذف رکورد <strong>${esc(u.name)}</strong> از داده‌های نمایشی مرورگر مطمئن هستید؟</p><div class="callout warning" style="margin-top:16px">این عملیات فقط رکورد محلی نسخه دمو را تغییر می‌دهد.</div><footer><button id="cancel-modal" class="btn btn-ghost">انصراف</button><button class="btn btn-danger" id="confirm-delete" data-id="${u.id}">حذف نمونه</button></footer>`);}
  function validPhone(value){const v=value.replace(/[\s\-()]/g,'');return /^(?:09\d{9}|\+989\d{9})$/.test(v);}
  function error(id,message){const field=$('#'+id)?.closest('.field');field?.classList.add('error');const el=$('#'+id+'-error');if(el)el.textContent=message;}
  function clearErrors(form){$$('.field',form).forEach(x=>x.classList.remove('error'));$$('.field-error',form).forEach(x=>x.textContent='');}
  function checkRequired(form,fields){clearErrors(form);let ok=true;for(const id of fields){const el=$('#'+id,form);if(!el||!el.value.trim()){error(id,'تکمیل این فیلد ضروری است.');ok=false;}}return ok;}
  function csvDownload(){const list=filteredUsers();const lines=[['ID','Name','Mobile','Email','Role','Status','Registration Date'],...list.map(u=>[u.id,u.name,u.phone,u.email,u.role,u.status,u.date])];const csv='\ufeff'+lines.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='nebula-demo-users.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('فایل CSV داده‌های نمونه دریافت شد.');}
  function render(){closeModal();let p=route();let content;if(['login','register','otp','forgot','reset','admin/login','secretary/login'].includes(p)){content=publicPage(p);}else if(p.startsWith('admin/')||p.startsWith('secretary/')){const panel=p.split('/')[0];const section=p.split('/')[1];if(!activeSession||activeSession.role!==panel){go(panel+'/login');content=publicPage(panel+'/login');}else if(panel==='secretary'){switch(section){case'dashboard':content=receptionistDashboard();break;case'appointments':content=appointmentPage('secretary');break;case'patients':content=patientPage('secretary');break;case'doctors':content=doctorPage('secretary');break;default:content=receptionistDashboard();}}else switch(section){case'secretaries':content=secretaryPage();break;case'appointments':content=appointmentPage('admin');break;case'patients':content=patientPage('admin');break;case'doctors':content=doctorPage('admin');break;case'dashboard':content=dashboard();break;case'users':content=userManagement();break;case'analytics':content=analytics();break;case'activity':content=activity();break;case'settings':content=settingsPage();break;case'profile':content=profile();break;default:content=publicPage('login');p='login';}}else{content=publicPage('login');p='login';}
    app.innerHTML=content;document.title=(routeNames[p.split('/')[1]]||({login:'ورود',register:'ثبت‌نام',otp:'کد تأیید',forgot:'بازیابی رمز',reset:'بازنشانی رمز','admin/login':'ورود مدیر'}[p])||'Nebula Access')+' | Nebula Access Pro';document.documentElement.lang='fa';document.documentElement.dir='rtl';updateMotion();initStory();window.scrollTo({top:0,behavior:'instant'});
  }
  function initStory(){let els=$$('.reveal');if(!els.length)return;if(!('IntersectionObserver'in window)){els.forEach(e=>e.classList.add('visible'));return;}const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}});},{threshold:.07});els.forEach(e=>observer.observe(e));}
  document.addEventListener('pointermove',e=>{const el=$('#tilt-scene');if(!el||innerWidth<900||!settings.animation||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const rect=el.getBoundingClientRect();const dx=(e.clientX-(rect.left+rect.width/2))/rect.width;const dy=(e.clientY-(rect.top+rect.height/2))/rect.height;el.style.transform=`rotateY(${Math.max(-8,Math.min(8,dx*9))}deg) rotateX(${Math.max(-8,Math.min(8,-dy*8))}deg)`;},{passive:true});
  document.addEventListener('click',e=>{
    const nav=e.target.closest('a[href="#/login"]');if(nav&&activeSession){e.preventDefault();demoLogout();return;}const t=e.target.closest('button');if(!t)return;
    if(t.classList.contains('demo-logout')){demoLogout();return;}
    if(t.id==='new-secretary')clinicModal('secretary');
    if(t.id==='new-patient')clinicModal('patient');
    if(t.id==='new-doctor')clinicModal('doctor');
    if(t.id==='new-appointment'){if(!patients.length||!doctors.length){toast('ابتدا پزشک و مراجع اضافه کنید.');return;}clinicModal('appointment');}
    for(const kind of ['secretary','patient','doctor','appointment']){if(t.dataset[kind+'Edit'])clinicModal(kind,Number(t.dataset[kind+'Edit']));if(t.dataset[kind+'Delete'])clinicDelete(kind,Number(t.dataset[kind+'Delete']));}
    if(t.dataset.togglePass){const el=$('#'+t.dataset.togglePass);if(el){el.type=el.type==='password'?'text':'password';t.setAttribute('aria-label',el.type==='password'?'نمایش رمز عبور':'پنهان کردن رمز عبور');t.innerHTML=icon(el.type==='password'?'eye':'hide','small');}}
    if(t.id==='mobile-menu'){$('#sidebar')?.classList.toggle('open');$('#mobile-overlay')?.classList.toggle('open');}
    if(t.id==='modal-close'||t.id==='cancel-modal')closeModal();
    if(t.dataset.edit)editUser(t.dataset.edit);
    if(t.dataset.delete)deleteUser(t.dataset.delete);
    if(t.id==='add-user')editUser(0);
    if(t.id==='confirm-delete'){users=users.filter(x=>x.id!==Number(t.dataset.id));saveUsers();closeModal();refreshUsers();toast('رکورد نمونه حذف شد.');}
    if(t.dataset.page){state.page=Number(t.dataset.page);refreshUsers();}
    if(t.id==='export-csv')csvDownload();
    if(t.id==='export-report')toast('خروجی گزارش عددی در نسخه نمایشی فعال نیست؛ CSV کاربران از صفحه مدیریت قابل دریافت است.');
    if(t.id==='resend-code')toast('پیامک واقعی ارسال نمی‌شود؛ هر کد ۶ رقمی نمونه پذیرفته می‌شود.');
    if(t.id==='reset-data'){if(confirm('داده‌های نمونه به وضعیت اولیه بازگردند؟')){users=structuredClone(originalUsers);secretaries=structuredClone(defaultSecretaries);patients=structuredClone(defaultPatients);doctors=structuredClone(defaultDoctors);appointments=structuredClone(defaultAppointments);saveUsers();saveClinic();toast('داده‌های نمونه بازنشانی شدند.');render();}}
  });
  document.addEventListener('mousedown',e=>{if(e.target.id==='mobile-overlay'){$('#sidebar')?.classList.remove('open');e.target.classList.remove('open');}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  document.addEventListener('input',e=>{
    if(e.target.id==='user-search'){state.search=e.target.value;state.page=1;refreshUsers();}
    if(e.target.id==='password'){const value=e.target.value;const score=[value.length>=8,/[A-Z]/.test(value),/[a-z]/.test(value),/\d/.test(value),/[^a-z\d]/i.test(value)].filter(Boolean).length;const fill=$('#strength-fill');if(fill){fill.style.width=score*20+'%';fill.style.background=score<2?'#ff809b':score<4?'#ffc774':'#3fe6ae';$('#strength-label').textContent=score<2?'قدرت رمز: ضعیف':score<4?'قدرت رمز: متوسط':'قدرت رمز: مناسب';}}
    if(e.target.matches('.otp-box')){e.target.value=e.target.value.replace(/[^\d۰-۹]/g,'').slice(-1);if(e.target.value)e.target.nextElementSibling?.focus();}
  });
  document.addEventListener('paste',e=>{if(!e.target.matches('.otp-box'))return;const text=(e.clipboardData||window.clipboardData)?.getData('text')||'';const d=text.replace(/[^\d]/g,'').slice(0,6);if(d.length){e.preventDefault();$$('.otp-box').forEach((el,i)=>el.value=d[i]||'');$$('.otp-box')[Math.min(d.length-1,5)]?.focus();}});
  document.addEventListener('change',e=>{
    if(e.target.id==='status-filter'){state.status=e.target.value;state.page=1;refreshUsers();}
    if(e.target.id==='role-filter'){state.role=e.target.value;state.page=1;refreshUsers();}
    if(e.target.id==='sort-filter'){state.sort=e.target.value;state.page=1;refreshUsers();}
    if(e.target.id==='activity-filter'){state.activityFilter=e.target.value;render();}
    if(e.target.id==='setting-motion'){settings.animation=e.target.checked;storageSet(settingsKey,settings);updateMotion();toast('تنظیمات حرکت ذخیره شد.');}
    if(e.target.id==='setting-compact'){settings.compact=e.target.checked;storageSet(settingsKey,settings);document.body.classList.toggle('compact',settings.compact);toast('تنظیمات نمایش ذخیره شد.');}
  });
  document.addEventListener('submit',e=>{
    const f=e.target;if(!f.id)return;e.preventDefault();
    if(f.id==='staff-login-form'){const role=f.dataset.role;const name=$('#staff-username').value.trim();const pass=$('#staff-password').value;if(!demoLogin(role,name,pass)){toast('نام کاربری یا رمز دمو اشتباه است یا حساب غیرفعال است.');return;}$('#staff-password').value='';toast('ورود نمایشی موفق بود.');go(role+'/dashboard');return;}
    if(f.id==='clinic-form'){saveClinicForm(f);return;}
    if(f.id==='login-form'){if(!checkRequired(f,['loginPhone','loginPassword']))return;if(!validPhone($('#loginPhone').value)){error('loginPhone','شماره موبایل نمونه باید با 09 یا +98 شروع شود.');return;}if($('#loginPassword').value.length<8){error('loginPassword','رمز نمونه حداقل ۸ نویسه داشته باشد.');return;}$('#loginPassword').value='';toast('ورود صرفاً نمایشی است؛ هیچ اطلاعاتی بررسی یا ارسال نشد.');go('login');}
    if(f.id==='register-form'){if(!checkRequired(f,['first','last','regPhone','password','confirm']))return;if(!validPhone($('#regPhone').value)){error('regPhone','شماره موبایل معتبر وارد کنید.');return;}if($('#email').value&&!$('#email').checkValidity()){error('email','ایمیل صحیح وارد کنید.');return;}if($('#password').value.length<8){error('password','حداقل ۸ نویسه لازم است.');return;}if($('#password').value!==$('#confirm').value){error('confirm','تکرار رمز مطابقت ندارد.');return;}if(!$('#agree').checked){toast('پذیرش شرایط نمایشی الزامی است.');return;}$('#password').value='';$('#confirm').value='';toast('فرم نمایشی بررسی شد. هیچ حساب واقعی ایجاد نشده است.');go('otp');}
    if(f.id==='otp-form'){const otp=$$('.otp-box').map(x=>x.value).join('');if(otp.length!==6){toast('۶ رقم نمونه وارد کنید.');return;}toast('کد صرفاً در حالت نمایشی پذیرفته شد.');go('login');}
    if(f.id==='forgot-form'){if(!validPhone($('#forgotPhone').value)){error('forgotPhone','شماره موبایل معتبر وارد کنید.');return;}toast('بازیابی نمایشی؛ هیچ پیامکی ارسال نشده است.');go('reset');}
    if(f.id==='reset-form'){if($('#newPassword').value.length<8){error('newPassword','حداقل ۸ نویسه وارد کنید.');return;}if($('#newPassword').value!==$('#newConfirm').value){error('newConfirm','رمزها یکسان نیستند.');return;}$('#newPassword').value='';$('#newConfirm').value='';toast('فرم بازنشانی نمونه تکمیل شد؛ هیچ رمز واقعی تغییر نکرد.');go('login');}
    if(f.id==='profile-form'){toast('ویرایش پروفایل صرفاً نمایشی است.');}
    if(f.id==='edit-user-form'){const name=$('#edit-name').value.trim(),phone=$('#edit-phone').value.trim(),email=$('#edit-email').value.trim();if(name.length<3){toast('نام باید حداقل ۳ نویسه باشد.');return;}if(!validPhone(phone)){toast('شماره موبایل معتبر وارد کنید.');return;}if(!$('#edit-email').checkValidity()||!email){toast('ایمیل معتبر وارد کنید.');return;}const id=Number(f.dataset.id);const data={name,phone,email,role:$('#edit-role').value,status:$('#edit-status').value};if(id){const u=users.find(x=>x.id===id);if(u)Object.assign(u,data);}else{users.push({id:Math.max(100,...users.map(x=>x.id))+1,...data,date:new Date().toLocaleDateString('fa-IR')});}saveUsers();closeModal();refreshUsers();toast(id?'کاربر نمونه ویرایش شد.':'کاربر نمونه افزوده شد.');}
  });
  document.body.classList.toggle('compact',settings.compact);addEventListener('hashchange',render);render();
})();
